// src/pages/PerfilAdmin.jsx
import React from 'react';
import { Link } from 'react-router-dom';
import HeaderPerfil from '../../components/HeaderPerfil'; // Importamos el nuevo componente
// importación de estilos globales o específicos de la página
//import "../../components/perfil_admin.css"; 

export default function PerfilAdmin() {
    return (
        // En lugar de <main>, es común envolver toda la página en un div o fragmento
        <div className="perfil-page-container"> 
            
            {/* Usamos el componente Header importado */}
            <HeaderPerfil />

            <main>
                <section className="perfil-box_2">
                    <h2>Perfil del Administrador</h2> 
                    
                    <div className="tarjeta_2">
                        <div className="info_2">
                            
                            {/* Dato 1: Nombre de usuario */}
                            <h4>
                                <strong>Nombre de usuario</strong><br />
                                <span className="dato_2">Andrea Gurama</span>
                            </h4>

                            {/* ... (resto de los datos: Correo, Teléfono, Identificación) ... */}
                            
                            <h4><strong>Correo electrónico</strong><br />
                                <span className="dato_2">usuario@gmail.com</span>
                            </h4>

                            <h4><strong>Número telefónico</strong><br />
                                <span className="dato">3287865455</span>
                            </h4>

                            <h4><strong>Identificación</strong><br />
                                <span className="dato">CC 1434500044</span>
                            </h4>

                        </div>

                        {/* Foto y rol */}
                        <div className="foto">
                            <img src="../assets/perfil_admi.png" alt="Foto del administrador" />
                            <h3 className="rol">Rol Administrador</h3>
                        </div>
                    </div>

                    {/* Acciones */}
                    <div className="acciones_2">
                        
                        {/* Acción 1: Cambiar datos */}
                        <Link to="/admin/editar_datosAd"> 
                            <button className="btn rosa">Cambiar datos</button>
                        </Link>

                        {/* Acción 2: Cambiar contraseña */}
                        <Link to="/admin/cambiar_c2"> 
                            <button className="btn rosa">Cambiar contraseña</button>
                        </Link>
                        
                        {/* Acción 3: Cerrar sesión */}
                        <Link to="/"> 
                            <button className="btn gris">Cerrar sesión</button>
                        </Link>
                    </div>
                </section>
            </main>
        </div>
    );
}
